WITH latest AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY order_id, carrier ORDER BY delivered_date DESC NULLS FIRST, id) AS rank_in_group FROM shipments QUALIFY rank_in_group = 1) SELECT CASE WHEN cost >= 102 THEN 'PREMIUM' ELSE 'STANDARD' END AS cost_tier, status, SUM(CASE WHEN status = 'LOST' THEN cost ELSE 0 END) AS lost_cost, COUNT_IF(status = 'LOST') AS lost_events, COUNT(*) FILTER (WHERE status = 'RETURNED') AS returned_rows, GROUPING_ID() AS gid FROM latest GROUP BY GROUPING SETS ((CASE WHEN cost >= 102 THEN 'PREMIUM' ELSE 'STANDARD' END, status), (CASE WHEN cost >= 102 THEN 'PREMIUM' ELSE 'STANDARD' END)) HAVING lost_cost > 0 ORDER BY status DESC;
